PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','project_manager','estimator','foreman')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS classifications (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, union_type TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS labor_rates (id TEXT PRIMARY KEY, classification_id TEXT NOT NULL REFERENCES classifications(id), effective_date TEXT NOT NULL, expiration_date TEXT, base_cents INTEGER NOT NULL, fringe_cents INTEGER NOT NULL, payroll_cents INTEGER NOT NULL, burden_cents INTEGER NOT NULL, ot_multiplier TEXT NOT NULL, dt_multiplier TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY, employee_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL, classification_id TEXT NOT NULL REFERENCES classifications(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cost_items (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, category TEXT NOT NULL CHECK(category IN ('equipment','material','disposal')), name TEXT NOT NULL, unit TEXT NOT NULL, metadata_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS item_rates (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES cost_items(id), effective_date TEXT NOT NULL, expiration_date TEXT, rate_cents INTEGER NOT NULL, basis_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, job_number TEXT NOT NULL UNIQUE, name TEXT NOT NULL, client TEXT NOT NULL, state TEXT NOT NULL, region TEXT NOT NULL, county TEXT NOT NULL, city TEXT NOT NULL, project_type TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, contract_cents INTEGER NOT NULL, budget_cents INTEGER NOT NULL, primary_activity TEXT NOT NULL, production_unit TEXT NOT NULL, contract_quantity TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','planned','completed')), notes TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_rates (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), item_id TEXT NOT NULL REFERENCES cost_items(id), effective_date TEXT NOT NULL, expiration_date TEXT, rate_cents INTEGER NOT NULL, source_note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), author_id TEXT NOT NULL REFERENCES users(id), work_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','approved')), transcript TEXT NOT NULL, audio_key TEXT, extraction_json TEXT, draft_json TEXT NOT NULL, approved_json TEXT, created_at TEXT NOT NULL, approved_at TEXT, approved_by TEXT REFERENCES users(id), revision INTEGER NOT NULL DEFAULT 0, submitted_at TEXT);
CREATE TABLE IF NOT EXISTS labor_entries (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id), classification_id TEXT NOT NULL REFERENCES classifications(id), workers INTEGER NOT NULL, regular_hours TEXT NOT NULL, ot_hours TEXT NOT NULL, dt_hours TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_entries (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id), item_id TEXT NOT NULL REFERENCES cost_items(id), quantity TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS production_entries (report_id TEXT PRIMARY KEY REFERENCES reports(id), activity TEXT NOT NULL, quantity TEXT NOT NULL, unit TEXT NOT NULL, workday_hours TEXT NOT NULL, depth TEXT, conditions TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cost_lines (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id), category TEXT NOT NULL, label TEXT NOT NULL, quantity TEXT NOT NULL, unit TEXT NOT NULL, rate_id TEXT NOT NULL, rate_source TEXT NOT NULL, rate_snapshot_json TEXT NOT NULL, cost_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, report_id TEXT NOT NULL UNIQUE REFERENCES reports(id), project_id TEXT NOT NULL REFERENCES projects(id), work_date TEXT NOT NULL, state TEXT NOT NULL, region TEXT NOT NULL, county TEXT NOT NULL, city TEXT NOT NULL, project_type TEXT NOT NULL, activity TEXT NOT NULL, unit TEXT NOT NULL, quantity TEXT NOT NULL, workday_hours TEXT NOT NULL, depth TEXT, conditions TEXT NOT NULL, labor_cents INTEGER NOT NULL, equipment_cents INTEGER NOT NULL, material_cents INTEGER NOT NULL, disposal_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, unit_cost_cents TEXT NOT NULL, production_per_hour TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reports_project_date ON reports(project_id,work_date);
CREATE INDEX IF NOT EXISTS observations_scope ON observations(activity,unit,region,work_date);
CREATE INDEX IF NOT EXISTS labor_rates_date ON labor_rates(classification_id,effective_date);
CREATE INDEX IF NOT EXISTS item_rates_date ON item_rates(item_id,effective_date);

CREATE TABLE IF NOT EXISTS project_members (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), assigned_by TEXT NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE INDEX IF NOT EXISTS project_members_user ON project_members(user_id,project_id);
